                        if int(frame[y][c0 + 2]) == 3), r1 + 1)
                  for r0, c0, r1, c1 in regions)
    positions = tuple(region(*f.centroid) for f in figures)
    targets = [(set(region(m.bbox[0], x)
                    for x in (m.bbox[1] - 1, m.bbox[3] + 1)), m.bbox[0])
